#include "bsp/native_shader_preload.hpp"

namespace bsp {

// Complete ordinary 00735F30..00735F7F schedule, 80 bytes/31 instructions.
// This public C++ interface borrows the EXISTING actual 0Ch vector header and
// allocation binding; it is distinct from native ECX/header, stack signed
// request and RET4. There is no established semantic native EAX result.
// Compare signed capacity first and call the concrete 735EC0 reserve service
// only when required. Growth reloads data each iteration, tests the calculated
// low32 slot address, and writes a zero DWORD there only when that address is
// nonzero. Its index wraps; growth makes no direct count-field publication.
// Shrink decrements the actual count field each iteration and compares its
// current signed value again. Always finish by storing the requested count.
// Preserve signed negative inputs, wrapping arithmetic, aliases and cycles;
// do not replace request0 with clear, free or per-element release. The actual
// reached storage and allocation/free services must satisfy their existing
// contracts. Invalid accesses may fault with preceding stores/effects retained.
// No validation, noexcept promise, catch, rollback or new cleanup is added.
// Original CRT/FH3/fault/service-register identity, callable Application tables,
// common owner construction and production wiring remain separate boundaries.
void resize_native_application_pointer_vector_00735f30(
    NativeApplicationPointerVectorStorage& actual_rows,
    std::int32_t requested,
    const NativeApplicationPointerVectorAllocation& allocation);

static_assert(sizeof(void*) == 4);
static_assert(sizeof(std::int32_t) == 4);
static_assert(offsetof(NativeApplicationPointerVectorStorage, data_00) == 0);
static_assert(offsetof(NativeApplicationPointerVectorStorage, count_04) == 4);
static_assert(offsetof(NativeApplicationPointerVectorStorage, capacity_08) == 8);

// Private Source ABI: ECX actual header, EDX borrowed allocation binding,
// stack signed request, RET4. Forward the same objects to the real reserve
// service; no copied binding, default callback or alternate allocation domain.
__declspec(noinline) void __fastcall reserve_for_resize(
    NativeApplicationPointerVectorStorage* actual_rows,
    const NativeApplicationPointerVectorAllocation* allocation,
    std::int32_t requested) {
    reserve_native_application_pointer_vector_00735ec0(
        *actual_rows, requested, *allocation);
}

// EDX carries the extra Source binding only as far as the sole reserve call.
// No preceding instruction changes EDX, and no later instruction needs it.
// The native stack layout and instruction schedule require no added spill.
__declspec(naked) void __fastcall resize_body(
    NativeApplicationPointerVectorStorage*,
    const NativeApplicationPointerVectorAllocation*, std::int32_t) {
    __asm {
        push esi                              // 00735F30
        push edi                              // 00735F31
        mov edi, dword ptr [esp + 0ch]         // 00735F32
        mov esi, ecx                          // 00735F36
        cmp edi, dword ptr [esi + 8]           // 00735F38
        jle short resize_current_count        // 00735F3B
        push edi                              // 00735F3D
        call reserve_for_resize               // 00735F3E

__declspec(noinline) void resize_native_application_pointer_vector_00735f30(
    NativeApplicationPointerVectorStorage& actual_rows,
    std::int32_t requested,
    const NativeApplicationPointerVectorAllocation& allocation) {
    resize_body(&actual_rows, &allocation, requested);
}

def verify(self):
    project = self.get('list_project_files', folder='/')
    info = self.get('get_current_program_info')
    expected = self.config
    if project['project_name'] != expected['project']:
        raise RuntimeError(f"Wrong Ghidra project: {project['project_name']}")
    for key, actual in [('program_path', info['path']), ('language', info['language']), ('image_base', info['image_base'])]:
        if actual != expected[key]:
            raise RuntimeError(f'Wrong target {key}: {actual}')
    return project, info
